begin;
create table if not exists public.income_categories(id bigint generated by default as identity primary key,name text not null unique,account_id bigint not null references public.accounts(id),status boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.incomes(id bigint generated by default as identity primary key,income_no text not null unique,category_id bigint not null references public.income_categories(id),income_date date not null default current_date,amount numeric(18,2) not null check(amount>0),payment_method text not null check(payment_method in('cash','bank')),description text not null,reference text,status text not null default 'posted' check(status in('posted','reversed')),reversal_reason text,reversed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists incomes_date_idx on public.incomes(income_date desc);create index if not exists incomes_category_idx on public.incomes(category_id);
create or replace function public.post_income(p_category_id bigint,p_income_date date,p_amount numeric,p_payment_method text,p_description text,p_reference text)
returns bigint language plpgsql security definer set search_path=public as $$
declare v_id bigint;v_no text;v_cash bigint;v_revenue bigint;
begin if p_amount<=0 then raise exception 'Amount must be positive';end if;if nullif(trim(p_description),'') is null then raise exception 'Description is required';end if;select account_id into v_revenue from public.income_categories where id=p_category_id and status=true;select id into v_cash from public.accounts where lower(account_type)=lower(p_payment_method) and status=true order by id limit 1;if v_revenue is null then raise exception 'Income category is not configured';end if;if v_cash is null then raise exception 'Cash or bank account is not configured';end if;v_no:='INC-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');insert into public.incomes(income_no,category_id,income_date,amount,payment_method,description,reference,created_by) values(v_no,p_category_id,coalesce(p_income_date,current_date),p_amount,p_payment_method,p_description,nullif(trim(p_reference),''),auth.uid()) returning id into v_id;insert into public.ledger_entries(account_id,transaction_date,description,debit,credit,reference_type,reference_id) values(v_cash,coalesce(p_income_date,current_date),v_no||' '||p_description,p_amount,0,'INCOME',v_id),(v_revenue,coalesce(p_income_date,current_date),v_no||' '||p_description,0,p_amount,'INCOME',v_id);return v_id;end;$$;
create or replace function public.reverse_income(p_income_id bigint,p_reason text)
returns void language plpgsql security definer set search_path=public as $$
declare v_income public.incomes;v_entry record;
begin if nullif(trim(p_reason),'') is null then raise exception 'Reversal reason is required';end if;select * into v_income from public.incomes where id=p_income_id for update;if v_income.id is null or v_income.status<>'posted' then raise exception 'Only posted income can be reversed';end if;for v_entry in select * from public.ledger_entries where reference_type='INCOME' and reference_id=p_income_id loop insert into public.ledger_entries(account_id,transaction_date,description,debit,credit,reference_type,reference_id) values(v_entry.account_id,current_date,'Reversal: '||v_income.income_no,v_entry.credit,v_entry.debit,'INCOME_REVERSAL',p_income_id);end loop;update public.incomes set status='reversed',reversal_reason=p_reason,reversed_at=now() where id=p_income_id;end;$$;
grant execute on function public.post_income(bigint,date,numeric,text,text,text) to authenticated;grant execute on function public.reverse_income(bigint,text) to authenticated;
alter table public.income_categories enable row level security;alter table public.incomes enable row level security;drop policy if exists authenticated_read_income_categories on public.income_categories;create policy authenticated_read_income_categories on public.income_categories for select to authenticated using(true);drop policy if exists authenticated_manage_income_categories on public.income_categories;create policy authenticated_manage_income_categories on public.income_categories for all to authenticated using(true) with check(true);drop policy if exists authenticated_read_incomes on public.incomes;create policy authenticated_read_incomes on public.incomes for select to authenticated using(true);
commit;
